import React, { useState, useEffect, useRef } from 'react';
import './App.css';

// Pixel art agent images
import agentNeutral from './assets/agent-neutral.png';
import agentHappy from './assets/agent-happy.png';
import agentConfused from './assets/agent-confused.png';
import agentThinking from './assets/agent-confused.png';

const PixelArtChat = () => {
  const [messages, setMessages] = useState([
    { text: "Welcome to your pixel art interview! I'll be your interviewer today.", sender: 'bot' }
  ]);
  const [inputMessage, setInputMessage] = useState('');
  const [role, setRole] = useState('Software Engineer');
  const [agentExpression, setAgentExpression] = useState('neutral');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef(null);

  const agentExpressions = {
    neutral: agentNeutral,
    happy: agentHappy,
    confused: agentConfused,
    thinking: agentThinking
  };

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const addMessage = (text, sender) => {
    setMessages(prev => [...prev, { text, sender }]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!inputMessage.trim() || isLoading) return;

    // Add user message
    addMessage(inputMessage, 'user');
    setInputMessage('');
    setAgentExpression('thinking');
    setIsLoading(true);

    try {
      // Get conversation history
      const history = messages.map(msg => 
        `${msg.sender === 'user' ? 'Candidate' : 'Interviewer'}: ${msg.text}`
      ).join('\n');

      // Call your backend API
      const response = await fetch('http://localhost:4001/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          message: inputMessage, 
          role,
          history 
        }),
      });

      const data = await response.json();
      addMessage(data.response, 'bot');
      
      // Update agent expression based on response
      const happyWords = ['great', 'excellent', 'good', 'perfect', 'well done'];
      const isPositive = happyWords.some(word => 
        data.response.toLowerCase().includes(word)
      );
      setAgentExpression(isPositive ? 'happy' : 'neutral');
      
    } catch (error) {
      console.error('Error:', error);
      addMessage("Sorry, I encountered an error. Please try again.", 'bot');
      setAgentExpression('confused');
    } finally {
      setIsLoading(false);
    }
  };

  const handleWrapUp = async () => {
    if (isLoading) return;
    setIsLoading(true);
    setAgentExpression('thinking');

    try {
      const history = messages.map(msg => 
        `${msg.sender === 'user' ? 'Candidate' : 'Interviewer'}: ${msg.text}`
      ).join('\n');

      const response = await fetch('http://localhost:4001/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          message: '__WRAP_UP__',
          role,
          history 
        }),
      });

      const data = await response.json();
      addMessage(data.response, 'bot');
      setAgentExpression('happy');
    } catch (error) {
      console.error('Error:', error);
      addMessage("Failed to wrap up the interview.", 'bot');
      setAgentExpression('confused');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="pixel-chat-container">
      <div className="chat-history-container">
        <div className="role-selector">
          <h2 className="pixel-header">Pixel Interviewer</h2>
          <select
            value={role}
            onChange={(e) => setRole(e.target.value)}
            className="pixel-select"
            disabled={isLoading}
          >
            <option value="Software Engineer">Software Engineer</option>
            <option value="Frontend Developer">Frontend Developer</option>
            <option value="Backend Developer">Backend Developer</option>
            <option value="Data Scientist">Data Scientist</option>
            <option value="UX Designer">UX Designer</option>
          </select>
        </div>

        <div className="chat-history">
          {messages.map((msg, i) => (
            <div key={i} className={`message ${msg.sender}`}>
              {msg.text}
            </div>
          ))}
          {isLoading && (
            <div className="message bot">
              <div className="typing-indicator">
                <span>•</span>
                <span>•</span>
                <span>•</span>
              </div>
            </div>
          )}
          <div ref={messagesEndRef} />
        </div>
      </div>

      <div className="pixel-scene">
        <img
          src={agentExpressions[agentExpression]}
          alt="Pixel Art Agent"
          className="pixel-agent"
        />
      </div>

      <div className="chat-ui">
        <form onSubmit={handleSubmit} className="input-area">
          <input
            type="text"
            value={inputMessage}
            onChange={(e) => setInputMessage(e.target.value)}
            placeholder="Type your response..."
            className="pixel-input"
            disabled={isLoading}
          />
          <button 
            type="submit" 
            className="pixel-button"
            disabled={isLoading}
          >
            {isLoading ? '...' : 'Send'}
          </button>
        </form>

        <button
          onClick={handleWrapUp}
          className="pixel-button wrap-up-button"
          disabled={isLoading}
        >
          Finish Interview
        </button>
      </div>
    </div>
  );
};

export default PixelArtChat;
